"""Samedi 21/11, session B. GPU 0 : proxy du tronc à 1e-4 (4 sujets exclus), un final de cette recette, 3 conversions courtes de finals existants en norme libre. GPU 1 : idem pour la recette avec moyenne d'essais de la même image. Chaque GPU enchaîne ses runs ; un run ne démarre que s'il peut finir avant le plafond.
Code embarqué (train_v3.py, models_v2.py) ; seuls les poids pré-entraînés REVE viennent de Hugging Face (public).
Généré par mk_runner_v3.py."""
import base64, glob, json, os, re, shutil, subprocess, sys, threading, time

QUEUES = {"0": [["nba_p", "--nocommon 1 --arch reve --rawnorm --bs 64 --amp --clip 1.0 --epochs 5 --lr 2e-4 --wd 0.05 --warmup 2000 --shift 3 --chdrop 0.1 --keep_epochs 3 --lr_backbone 1e-4 --eval_light --save_preds --time_limit 10900 --need_s 11750"], ["final_nba_s73", "--nocommon 1 --arch reve --rawnorm --bs 64 --amp --clip 1.0 --epochs 5 --lr 2e-4 --wd 0.05 --warmup 2000 --shift 3 --chdrop 0.1 --keep_epochs 3 --lr_backbone 1e-4 --holdout 0 --init_seed 73 --time_limit 18300 --need_s 19100"], ["rwft_revef_c", "--arch revef --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from revef_c/best.pt --init_seed 61"], ["rwft_final_reve_s0", "--arch reve --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from final_reve_s0/last.pt --init_seed 63"], ["rwft_final_revef_c_s10", "--arch revef --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from final_revef_c_s10/last.pt --init_seed 65"]], "1": [["nbm_p", "--nocommon 1 --arch reve --rawnorm --bs 64 --amp --clip 1.0 --epochs 5 --lr 2e-4 --wd 0.05 --warmup 2000 --shift 3 --chdrop 0.1 --keep_epochs 3 --lr_backbone 1e-4 --mix 0.5 --mixk 6 --eval_light --save_preds --time_limit 10900 --need_s 11750"], ["final_nbm_s78", "--nocommon 1 --arch reve --rawnorm --bs 64 --amp --clip 1.0 --epochs 5 --lr 2e-4 --wd 0.05 --warmup 2000 --shift 3 --chdrop 0.1 --keep_epochs 3 --lr_backbone 1e-4 --mix 0.5 --mixk 6 --holdout 0 --init_seed 78 --time_limit 18300 --need_s 19100"], ["rwft_final_reve_c_s2", "--arch reve --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from final_reve_c_s2/last.pt --init_seed 62"], ["rwft_final_reve_s1", "--arch reve --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from final_reve_s1/last.pt --init_seed 66"], ["rwft_final_reve_d_s7", "--arch reve --rawnorm --holdout 0 --reve none --epochs 1 --epoch_frac 0.47 --lr 3e-4 --lr_backbone 1e-4 --warmup 100 --init_from final_reve_d_s7/last.pt --init_seed 64"]]}
COMMON = "--bs 512 --amp --clip 1.0 --sym --learn_temp --mix 0.3 --shift 3 --chdrop 0.1 --noise 0.1 --gneg 0.5 --soft 0.02"
TIMEOUT = int(10.9 * 3600)        # compté APRÈS la copie des données
HARD = int(11.6 * 3600)                # depuis le début du script : Kaggle coupe la session à 12 h
SEC_FINAL, SEC_PROXY, STARTUP = 3150, 2100, 700      # REVE-base par passe : final 3 241 lots ; proxy 1 896 lots + évaluation
SEC_FINAL_L, SEC_PROXY_L = 15000, 9100               # REVE-large (recalcul des activations), par passe
CHECK_LOT, CHECK_MAX = 1200, 7.82   # santé : perte au lot CHECK_LOT de la 1re passe (0 = pas de contrôle)
DRY = bool(os.environ.get("NI_DRY"))   # essai à sec, sans GPU : faux entraîneur, durées divisées par NI_DRY_SCALE
SCALE = float(os.environ.get("NI_DRY_SCALE", "1000")) if DRY else 1.0
WORK = os.environ.get("NI_WORK", "/kaggle/working")
INPUT = os.environ.get("NI_INPUT", "/kaggle/input")
POLL = 30 / SCALE if DRY else 30
T_SCRIPT = time.time()
CODE = {"train_v3.py": "", "models_v2.py": ""}

os.makedirs(f"{WORK}/code", exist_ok=True)
for n, b in CODE.items():
    open(f"{WORK}/code/{n}", "wb").write(base64.b64decode(b))
code = f"{WORK}/code/train_v3.py"
CK = {"none": ""}
if DRY:
    code, fast, n_gpu = os.environ["NI_DRY_TRAINER"], "/tmp", int(os.environ.get("NI_DRY_GPUS", "2"))
    CK.update(base="", large="")
else:
    from huggingface_hub import hf_hub_download
    need_ck = {(re.findall(r"--reve (\w+)", a) or ["base"])[-1] for q in QUEUES.values() for _, a in q}
    if "base" in need_ck:
        CK["base"] = hf_hub_download("brain-bzh/reve-base", "model.safetensors")
    if "large" in need_ck:
        CK["large"] = hf_hub_download("brain-bzh/reve-large", "model.safetensors")
    fast = os.path.dirname(glob.glob(f"{INPUT}/**/signal_f16.npy", recursive=True)[0])
    r = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total", "--format=csv,noheader"],
                       capture_output=True, text=True)
    print(r.stdout, flush=True)
    n_gpu = len([l for l in r.stdout.splitlines() if l.strip()])
    # --- données : copie séquentielle sur le disque local, une fois, avant tout entraînement ---
    tc = time.time()
    local = "/tmp/ni_fast"
    try:
        os.makedirs(local, exist_ok=True)
        for f in sorted(os.listdir(fast)):          # recs.json, index.npz, targets.npy, stims.json, signal_f16.npy...
            if os.path.isfile(os.path.join(fast, f)):
                shutil.copyfile(os.path.join(fast, f), os.path.join(local, f))
        assert os.path.getsize(os.path.join(local, "signal_f16.npy")) == os.path.getsize(os.path.join(fast, "signal_f16.npy"))
        fast = local
        print(f"données copiées dans {local} en {time.time() - tc:.0f} s", flush=True)
    except Exception as e:      # disque local plein, etc. : on lit au moins le signal une fois (cache disque chaud)
        print(f"copie locale impossible ({e!r}) : lecture du signal en place", flush=True)
        with open(os.path.join(fast, "signal_f16.npy"), "rb") as h:
            while h.read(1 << 26):
                pass
        print(f"signal lu en {time.time() - tc:.0f} s", flush=True)
print("code", code, "| alljoined", fast, "| reve", CK, "| GPU", n_gpu, flush=True)
if 0 < n_gpu < len(QUEUES):     # un seul GPU attribué : tout s'enchaîne sur le GPU 0, dans l'ordre des files
    print(f"ATTENTION : {n_gpu} GPU pour {len(QUEUES)} files, files fusionnées sur le GPU 0", flush=True)
    QUEUES = {"0": [r for g in sorted(QUEUES, key=int) for r in QUEUES[g]]}
os.makedirs(WORK, exist_ok=True)
t0 = time.time()                # le plafond TIMEOUT part d'ici (démarrage non compté)
LIMIT = min(t0 + TIMEOUT / SCALE, T_SCRIPT + HARD / SCALE)     # instant absolu de fin
procs, done, skipped, unstable, cut, failed = {}, [], [], [], [], []
OPTS = r"--(?:reve|init_from|need_s|nocommon) \S+"      # options du lanceur, retirées avant d'appeler train_v3


def opt(args, name, default=None):
    m = re.findall(rf"--{name} (\S+)", args)
    return m[-1] if m else default


def need_s(args):
    if opt(args, "need_s"):
        return float(opt(args, "need_s")) / SCALE
    full = ("" if opt(args, "nocommon") else COMMON) + " " + args
    ep = int(opt(full, "stop_epoch", 0)) or int(opt(full, "epochs", 3))
    final = opt(full, "holdout", "4") == "0"
    large = opt(full, "arch", "reve").startswith("revel")
    per = (SEC_FINAL_L if final else SEC_PROXY_L) if large else (SEC_FINAL if final else SEC_PROXY)
    return (ep * per * float(opt(full, "epoch_frac", 1.0)) + STARTUP) / SCALE


def health(name):
    """None tant que le lot de contrôle n'est pas atteint, sinon la perte lue à ce lot."""
    if not CHECK_LOT:
        return None
    try:
        m = re.search(rf"ep 0 lot {CHECK_LOT}/\d+ loss ([\d.]+)", open(f"{WORK}/{name}.out").read())
    except OSError:
        return None
    return float(m.group(1)) if m else None


def launch(gpu, name, extra):
    env = dict(os.environ, NI_FAST=fast, NI_OUT=f"{WORK}/outputs", CUDA_VISIBLE_DEVICES=str(gpu))
    ck = CK[opt(extra, "reve", "base")]
    env.pop("NI_REVE", None)
    if ck:
        env["NI_REVE"] = ck
    init = opt(extra, "init_from")
    common = [] if opt(extra, "nocommon") else COMMON.split()
    extra = re.sub(OPTS, "", extra)
    if init:
        found = sorted(glob.glob(f"{INPUT}/**/{init}", recursive=True))
        assert found, f"point de contrôle introuvable : {init}"
        extra += f" --init {found[0]}"
    cmd = [sys.executable, "-u", code, "--name", name, "--device", "cuda"] + common + extra.split()
    print(f"[GPU {gpu}] {time.strftime('%H:%M')} " + " ".join(cmd), flush=True)
    return subprocess.Popen(cmd, env=env, stdout=open(f"{WORK}/{name}.out", "w"), stderr=subprocess.STDOUT)


def worker(gpu, runs):
    runs = list(runs)
    while runs:
        name, extra = runs.pop(0)
        need = need_s(extra)
        if time.time() + need > LIMIT:
            skipped.append(name)
            print(f"[GPU {gpu}] {name} non démarré : {need * SCALE:.0f} s nécessaires, "
                  f"{(LIMIT - time.time()) * SCALE:.0f} s restants", flush=True)
            continue
        try:
            p = procs[name] = launch(gpu, name, extra)
        except Exception as e:
            failed.append(name)
            print(f"[GPU {gpu}] {name} ÉCHEC au lancement : {e!r}", flush=True)
            continue
        checked = False
        while p.poll() is None:
            time.sleep(POLL)
            loss = None if checked else health(name)
            if loss is not None:
                checked = True
                if loss > CHECK_MAX:
                    p.kill(); p.wait()
                    print(f"[GPU {gpu}] {name} INSTABLE (perte {loss:.3f} au lot {CHECK_LOT}) : arrêté", flush=True)
                    unstable.append(name)
                    shutil.rmtree(f"{WORK}/outputs/{name}", ignore_errors=True)
                    seed = int(opt(extra, "init_seed", 0)) + 100
                    retry = re.sub(r"--init_seed \d+", "", extra) + f" --init_seed {seed}"
                    if not name.endswith("_r"):          # une seule relance par run
                        runs.insert(0, (name + "_r", retry))     # en tête de file, si le temps le permet
        if name in unstable or name in cut:
            continue
        if p.returncode == 0:
            done.append(name)
            print(f"[GPU {gpu}] {time.strftime('%H:%M')} {name} fini", flush=True)
        else:
            failed.append(name)
            print(f"[GPU {gpu}] {time.strftime('%H:%M')} {name} ÉCHEC (code {p.returncode}), voir {name}.out", flush=True)


threads = [threading.Thread(target=worker, args=(int(g), r), daemon=True) for g, r in QUEUES.items()]
for t in threads:
    t.start()
while any(t.is_alive() for t in threads) and time.time() < LIMIT:
    time.sleep(POLL)
for name, p in list(procs.items()):
    if p.poll() is None:
        cut.append(name)
        p.kill(); p.wait()
        print(f"plafond atteint : {name} arrêté (inachevé, à ne pas utiliser)", flush=True)
for t in threads:
    t.join(timeout=5 * POLL)
for name in procs:              # final : best.pt est une copie de last.pt (sortie deux fois moins lourde)
    cfg, b, l = (f"{WORK}/outputs/{name}/{f}" for f in ("config.json", "best.pt", "last.pt"))
    try:
        if os.path.exists(b) and os.path.exists(l) and (json.load(open(cfg)).get("holdout") == 0 or True):
            os.remove(b if json.load(open(cfg)).get("holdout") == 0 else l)
    except Exception as e:
        print("nettoyage", name, repr(e), flush=True)
shutil.rmtree(f"{WORK}/code", ignore_errors=True)
print("finis :", done, "| instables :", unstable, "| échecs :", failed, "| non démarrés :", skipped, "| coupés :", cut,
      f"| durée {(time.time() - T_SCRIPT) * SCALE / 3600:.2f} h", flush=True)
json.dump(dict(done=done, unstable=unstable, failed=failed, skipped=skipped, cut=cut), open(f"{WORK}/resume.json", "w"))
for name in procs:
    print(f"===== {name}", flush=True)
    try:
        print("".join(open(f"{WORK}/{name}.out").readlines()[-10:]), flush=True)
    except OSError:
        pass
